#!/usr/bin/env python3
"""Compare the paper's regenerated files with the ones its checkout has committed.

A .tex file must match line for line apart from its stamp line ("%% Generated by ..."), which names the commit that
wrote it. A .pdf must match in its text content (pdftotext), so tick labels and numbers count while metadata does not.
Experiments named in --measured (timings and the like) are reported, never failed.

Usage: compare_generated.py PAPER [--measured name ...]
"""
import argparse
import pathlib
import subprocess
import sys
import tempfile

STAMP = "%% Generated by"


def committed(paper: pathlib.Path, rel: str) -> bytes | None:
    r = subprocess.run(["git", "-C", str(paper), "show", f"HEAD:{rel}"], capture_output=True)
    return r.stdout if r.returncode == 0 else None


def pdf_text(data: bytes) -> str:
    with tempfile.NamedTemporaryFile(suffix=".pdf") as f:
        f.write(data)
        f.flush()
        return subprocess.run(["pdftotext", "-layout", f.name, "-"], capture_output=True, text=True, check=True).stdout


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("paper", type=pathlib.Path)
    ap.add_argument("--measured", nargs="*", default=[])
    a = ap.parse_args()
    bad = 0
    for path in sorted((a.paper / "generated").iterdir()):
        rel = f"generated/{path.name}"
        old = committed(a.paper, rel)
        new = path.read_bytes()
        if old is None:
            print(f"NEW: {rel}")
            continue
        if path.suffix == ".tex":
            strip = lambda b: [l for l in b.decode().splitlines() if not l.startswith(STAMP)]
            same = strip(old) == strip(new)
        elif path.suffix == ".pdf":
            same = pdf_text(old) == pdf_text(new)
        else:
            same = old == new
        if same:
            print(f"same: {rel}")
        elif path.stem in a.measured:
            print(f"re-measured: {rel}")
        else:
            print(f"CHANGED: {rel}")
            bad = 1
    if bad:
        print("deterministic outputs changed: say why in the pull request, or find out")
    return bad


if __name__ == "__main__":
    sys.exit(main())
